From 2c148e6411021798dcf5a8732008e8d5507c0226 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 03:52:09 +0100
Subject: [PATCH] libkmpris: Show the volume OSD once the player applies the
 change

Chromium accepts setting its MPRIS Volume but ignores it, so the media
volume shortcuts moved the OSD while the volume stayed the same. Show
the OSD from the volume the player reports, and keep only that value.

CCBUG: 526656
---
 libkmpris/playercontainer.cpp | 58 +++++++++++++++++++++++------------
 libkmpris/playercontainer.h   |  5 +++
 2 files changed, 43 insertions(+), 20 deletions(-)

diff --git a/libkmpris/playercontainer.cpp b/libkmpris/playercontainer.cpp
index 933eebaf9b..df0b7341dc 100644
--- a/libkmpris/playercontainer.cpp
+++ b/libkmpris/playercontainer.cpp
@@ -435,35 +435,44 @@ void PlayerContainer::updatePosition()

 void PlayerContainer::changeVolume(double delta, bool showOSD)
 {
-    // Not relying on property/setProperty to avoid doing blocking DBus calls
-    const double newVolume = qBound(0.0, m_volume + delta, std::max(m_volume.value(), 1.0));
-    const double oldVolume = m_volume;
+    // Not relying on property/setProperty to avoid doing blocking DBus calls.
+    // When calling this method in quick succession (mouse wheeling the tray icon)
+    // continue from the volume asked for until the player reports it
+    const double oldVolume = m_volumeChangesPending > 0 ? m_requestedVolume : m_volume.value();
+    const double newVolume = qBound(0.0, oldVolume + delta, std::max(oldVolume, 1.0));
+
+    if (qFuzzyCompare(1.0 + newVolume, 1.0 + oldVolume)) {
+        if (showOSD && m_volumeChangesPending == 0) {
+            showVolumeOSD();
+        }
+        return;
+    }

-    // Update the container value right away so when calling this method in quick succession
-    // (mouse wheeling the tray icon) next call already gets the new value
-    m_volume = newVolume;
+    m_volumeOSDPending = m_volumeOSDPending || showOSD;
+    m_requestedVolume = newVolume;
+    ++m_volumeChangesPending;

     QDBusPendingCall call = m_propsIface->Set(m_playerIface->interface(), QStringLiteral("Volume"), QDBusVariant(newVolume));
     auto watcher = new QDBusPendingCallWatcher(call, this);
-    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, oldVolume, showOSD](QDBusPendingCallWatcher *watcher) {
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
         QDBusPendingReply<void> reply = *watcher;
         watcher->deleteLater();
-        if (!reply.isValid()) {
-            m_volume = oldVolume;
-            return;
+        if (!reply.isValid() && m_volumeChangesPending > 0 && --m_volumeChangesPending == 0) {
+            m_volumeOSDPending = false;
         }
+    });
+}

-        if (showOSD) {
-            QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
-                                                              QStringLiteral("/org/kde/osdService"),
-                                                              QStringLiteral("org.kde.osdService"),
-                                                              QStringLiteral("mediaPlayerVolumeChanged"));
+void PlayerContainer::showVolumeOSD()
+{
+    QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
+                                                      QStringLiteral("/org/kde/osdService"),
+                                                      QStringLiteral("org.kde.osdService"),
+                                                      QStringLiteral("mediaPlayerVolumeChanged"));

-            msg.setArguments({qRound(m_volume * 100), m_identity, m_iconName});
+    msg.setArguments({qRound(m_volume * 100), m_identity, m_iconName});

-            QDBusConnection::sessionBus().asyncCall(msg);
-        }
-    });
+    QDBusConnection::sessionBus().asyncCall(msg);
 }

 void PlayerContainer::initBindings()
@@ -605,7 +614,16 @@ void PlayerContainer::updateFromMap(const QVariantMap &map)
         } else if (propName == QLatin1String("MaximumRate")) {
             m_maximumRate = it->toDouble();
         } else if (propName == QLatin1String("Volume")) {
-            m_volume = it->toDouble();
+            // Only show the OSD once the player applied the change, as some accept it but ignore it
+            const double volume = it->toDouble();
+            const bool volumeChanged = !qFuzzyCompare(1.0 + volume, 1.0 + m_volume.value());
+            m_volume = volume;
+            if (volumeChanged && m_volumeOSDPending) {
+                showVolumeOSD();
+            }
+            if (m_volumeChangesPending > 0 && --m_volumeChangesPending == 0) {
+                m_volumeOSDPending = false;
+            }
         } else if (propName == QLatin1String("Position")) {
             m_position = it->toLongLong();
         } else if (propName == QLatin1String("Metadata")) {
diff --git a/libkmpris/playercontainer.h b/libkmpris/playercontainer.h
index d3686fddfd..a4198122c9 100644
--- a/libkmpris/playercontainer.h
+++ b/libkmpris/playercontainer.h
@@ -322,6 +322,7 @@ private:
     void initBindings();
     void updateFromMap(const QVariantMap &map);
     void updateFromService(const KService::Ptr &service);
+    void showVolumeOSD();

     int m_fetchesPending = 0;
     QString m_dbusAddress;
@@ -329,6 +330,10 @@ private:
     OrgMprisMediaPlayer2PlayerInterface *m_playerIface = nullptr;
     OrgMprisMediaPlayer2Interface *m_rootIface = nullptr;

+    int m_volumeChangesPending = 0;
+    double m_requestedVolume = 0.0;
+    bool m_volumeOSDPending = false;
+
     QPropertyNotifier m_rateNotifier;
     QPropertyNotifier m_playbackStatusNotifier;
 };
